381	    private <T> T findEntityById(Supplier<T> supplier) {
382	        try {
383	            return supplier.get();
384	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
385	            // Just ignore not found exceptions for Jdbc/Jpa realization
386	            return null;
387	        }
388	    }
389	
