297	    public Integer getMembershipLevelCap() {
298	        return this.membershipLevelCap;
299	    }
300	
301	    public void setMembershipLevelCap(Integer membershipLevelCap) {
302	        this.membershipLevelCap = membershipLevelCap;
303	    }
304	
305	    /**
306	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
307	     * is the last two digits of the registration date's fiscal year (see {@link FiscalYear};
308	     * e.g. {@code "NSW-1A2B3C4D-M26"}). Derived from the owner's own fields, so it stays
309	     * consistent with them, including its {@link #getFiscalYear() fiscal year}.
310	     */
311	    @Transient
312	    public String getMembershipNumber() {
313	        if (this.customerCode == null || this.registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("%s-M%02d", this.customerCode, FiscalYear.shortYearOf(this.registrationDate));
317	    }
318	
319	    /**
320	     * The owner's fiscal year: the {@code 'FY<YY>'} label of the fiscal year (which starts
321	     * on 1 July) that their business-day-adjusted registration date falls in (see
322	     * {@link FiscalYear}). Derived from the owner's own registration date, so it stays
323	     * consistent with it; null until a registration date is on file.
324	     */
325	    @Transient
326	    public String getFiscalYear() {
327	        if (this.registrationDate == null) {
328	            return null;
329	        }
330	        return FiscalYear.labelFor(this.registrationDate);
331	    }
332	
333	    /**
334	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
335	     * over the digits of the customer code. Derived from the owner's own customer code,
336	     * so it stays consistent with it.
337	     */
338	    @Transient
339	    public Integer getCheckDigit() {
340	        if (this.customerCode == null) {
341	            return null;
342	        }
343	        return LuhnCheckDigit.of(this.customerCode);
344	    }
345	
346	    /**
347	     * The owner's membership points, starting at zero: two points are added when an email is
348	     * on file, one more when the owner is unique (namesake count of zero), two more for a
349	     * household of three or more, and three more when the owner has accrued more than a fiscal
350	     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
351	     * consistent with them.
352	     */
353	    @Transient
354	    public Integer getMembershipPoints() {
355	        int points = 0;
356	        boolean hasEmail = this.email != null && !this.email.isEmpty();
357	        if (hasEmail) {
358	            points += 2;
359	        }
360	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
361	        if (unique) {
362	            points += 1;
363	        }
364	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
365	        if (largeHousehold) {
366	            points += 2;
367	        }
368	        boolean tenured = this.registrationDate != null
369	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
370	        if (tenured) {
371	            points += 3;
372	        }
373	        return points;
374	    }
375	
376	    /**
377	     * The owner's membership level, a number from 1 to 4, derived from their
378	     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}), then
379	     * held down to its {@link #getMembershipLevelCap() household ceiling} when one applies.
380	     * Derived from the owner's own fields, so it stays consistent with them.
381	     */
382	    @Transient
383	    public Integer getMembershipLevel() {
384	        int level = MembershipLevel.forPoints(getMembershipPoints());
385	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
386	            return this.membershipLevelCap;
387	        }
388	        return level;
389	    }
390	
391	    /**
392	     * The owner's locality: the canonical region, taken as the region segment of the
393	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
394	     * consistent with the owner's identity. When no customer code has been assigned yet
395	     * it falls back to resolving the region directly from the postcode and city (see
396	     * {@link RegionResolver}), the same rule the customer code itself is built from.
397	     */
398	    @Transient
399	    public String getLocality() {
400	        if (this.customerCode != null) {
401	            int separator = this.customerCode.indexOf('-');
402	            if (separator > 0) {
403	                return this.customerCode.substring(0, separator);
404	            }
405	        }
406	        return RegionResolver.regionFor(this.postcode, this.city);
407	    }
408	
409	    /**
410	     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
411	     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
412	     * stays consistent with the owner's region. Null when the locality has no known timezone.
413	     */
414	    @Transient
415	    public String getTimezone() {
416	        return RegionTimezoneTable.timezoneFor(getLocality());
417	    }
418	
419	    /**
420	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
421	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
422	     * stays consistent with them.
423	     */
424	    @Transient
425	    public String getContactPreference() {
426	        boolean hasEmail = this.email != null && !this.email.isEmpty();
427	        return hasEmail ? "EMAIL" : "PHONE";
428	    }
429	
430	    /**
431	     * The owner's telephone formatted for human display: the stored E.164 number
432	     * rendered as its country calling code, a space and the national digits grouped
433	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
434	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
435	     * consistent with it. See {@link TelephoneFormatter}.
436	     */
437	    @Transient
438	    public String getTelephoneDisplay() {
439	        return TelephoneFormatter.toDisplay(this.telephone);
440	    }
441	
442	    /**
443	     * The owner's identity key: the single derived value used to detect duplicate owners,
444	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
445	     * Two owners are duplicates only when their whole identity keys are equal, so members
446	     * of one household (sharing a household id) but with different telephones stay distinct.
447	     * Derived from the owner's own fields, so it stays consistent with them.
448	     */
449	    @Transient
450	    public String getIdentityKey() {
451	        String telephonePart = this.telephone == null ? "" : this.telephone;
452	        String emailPart = this.email == null ? "" : this.email;
453	        String householdPart = this.householdId == null ? "" : this.householdId;
454	        return telephonePart + "|" + emailPart + "|" + householdPart;
455	    }
456	
457	    /**
458	     * The owner's age band relative to their registration date: {@code "MINOR"} when
459	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
460	     * Derived from the owner's own birth and registration dates, so it stays consistent
461	     * with them; null until a birth date is on file. See {@link AgeBand}.
462	     */
463	    @Transient
464	    public String getAgeBand() {
465	        if (this.birthDate == null || this.registrationDate == null) {
466	            return null;
467	        }
468	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
469	    }
470	
471	    /**
472	     * Normalize the registration date before persisting: default it to the server's
473	     * current date when none was supplied, then roll it forward onto a business day so
474	     * every newly persisted owner is registered on a weekday.
475	     */
476	    @PrePersist
477	    void normalizeRegistrationDate() {
478	        if (this.registrationDate == null) {
479	            this.registrationDate = LocalDate.now();
480	        }
481	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
482	    }
483	
484	    protected Set<Pet> getPetsInternal() {
485	        if (this.pets == null) {
486	            this.pets = new HashSet<>();
487	        }
488	        return this.pets;
489	    }
490	
491	    protected void setPetsInternal(Set<Pet> pets) {
492	        this.pets = pets;
493	    }
494	
495	    public List<Pet> getPets() {
496	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
497	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
498	        return Collections.unmodifiableList(sortedPets);
499	    }
500	
501	    public void setPets(List<Pet> pets) {
502	        this.pets = new HashSet<>(pets);
503	    }
504	
505	    public void addPet(Pet pet) {
506	        getPetsInternal().add(pet);
507	        pet.setOwner(this);
508	    }
509	
510	    /**
511	     * Return the Pet with the given name, or null if none found for this Owner.
512	     *
513	     * @param name to test
514	     * @return true if pet name is already in use
515	     */
516	    public Pet getPet(String name) {
517	        return getPet(name, false);
518	    }
519	
520	    /**
521	     * Return the Pet with the given name, or null if none found for this Owner.
522	     *
523	     * @param name to test
524	     * @return true if pet name is already in use
525	     */
526	    public Pet getPet(String name, boolean ignoreNew) {
527	        name = name.toLowerCase();
528	        for (Pet pet : getPetsInternal()) {
529	            if (!ignoreNew || !pet.isNew()) {
530	                String compName = pet.getName();
531	                compName = compName.toLowerCase();
532	                if (compName.equals(name)) {
533	                    return pet;
534	                }
535	            }
536	        }
537	        return null;
538	    }
539	
540	    public Pet getPet(Integer petId) {
541	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
542	    }
543	
544	    @Override
545	    public String toString() {
546	        return new ToStringCreator(this)
547	
548	            .append("id", this.getId())
549	            .append("new", this.isNew())
550	            .append("lastName", this.getLastName())
551	            .append("firstName", this.getFirstName())
552	            .append("address", this.address)
553	            .append("city", this.city)
554	            .append("telephone", this.telephone)
555	            .toString();
556	    }
557	}
