17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Computes the SHA-256 digest of a string as lower-case hexadecimal. Shared by the
24	 * owner identity generators so the hashing is written in exactly one place.
25	 */
26	final class Sha256 {
27	
28	    private Sha256() {
29	    }
30	
31	    /**
32	     * The lower-case hexadecimal SHA-256 digest of the UTF-8 bytes of {@code value}.
33	     */
34	    static String hex(String value) {
35	        try {
36	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
37	            StringBuilder hex = new StringBuilder(digest.length * 2);
38	            for (byte b : digest) {
39	                hex.append(String.format("%02x", b));
40	            }
41	            return hex.toString();
42	        }
43	        catch (NoSuchAlgorithmException e) {
44	            throw new IllegalStateException("SHA-256 is required but not available", e);
45	        }
46	    }
47	}
