335	    /**
336	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate
337	     * of: one that occupies the same household (the same computed household id) but carries
338	     * a different telephone, so it is not a hard duplicate. When several match, the earliest
339	     * (lowest id) is chosen. An owner that belongs to no household (no household id), or one
340	     * that deliberately declared it shares a household, is never a suspected duplicate.
341	     */
342	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
343	        if (owner.isDeclaredHouseholdMember()) {
344	            return Optional.empty();
345	        }
346	        return existingHouseholdMembers(owner).stream()
347	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
348	            .min(Comparator.comparing(Owner::getId));
349	    }
