346	    /**
347	     * The owner's membership points, starting at zero: two points are added when an email is
348	     * on file, one more when the owner is unique (namesake count of zero), two more for a
349	     * household of three or more, and three more when the owner has accrued more than a fiscal
350	     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
351	     * consistent with them.
352	     */
353	    @Transient
354	    public Integer getMembershipPoints() {
355	        int points = 0;
356	        boolean hasEmail = this.email != null && !this.email.isEmpty();
357	        if (hasEmail) {
358	            points += 2;
359	        }
360	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
361	        if (unique) {
362	            points += 1;
363	        }
364	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
365	        if (largeHousehold) {
366	            points += 2;
367	        }
368	        boolean tenured = this.registrationDate != null
369	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
370	        if (tenured) {
371	            points += 3;
372	        }
373	        return points;
374	    }
