441	
442	    /**
443	     * The owner's identity key: the single derived value used to detect duplicate owners,
444	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
445	     * Two owners are duplicates only when their whole identity keys are equal, so members
446	     * of one household (sharing a household id) but with different telephones stay distinct.
447	     * Derived from the owner's own fields, so it stays consistent with them.
448	     */
449	    @Transient
450	    public String getIdentityKey() {
451	        String telephonePart = this.telephone == null ? "" : this.telephone;
452	        String emailPart = this.email == null ? "" : this.email;
453	        String householdPart = this.householdId == null ? "" : this.householdId;
454	        return telephonePart + "|" + emailPart + "|" + householdPart;
455	    }
456	
457	    /**
458	     * The owner's age band relative to their registration date: {@code "MINOR"} when
459	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
460	     * Derived from the owner's own birth and registration dates, so it stays consistent
461	     * with them; null until a birth date is on file. See {@link AgeBand}.
462	     */
463	    @Transient
464	    public String getAgeBand() {
465	        if (this.birthDate == null || this.registrationDate == null) {
466	            return null;
467	        }
468	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
469	    }
470	
471	    /**
472	     * Normalize the registration date before persisting: default it to the server's
473	     * current date when none was supplied, then roll it forward onto a business day so
474	     * every newly persisted owner is registered on a weekday.
475	     */
476	    @PrePersist
477	    void normalizeRegistrationDate() {
478	        if (this.registrationDate == null) {
479	            this.registrationDate = LocalDate.now();
480	        }
481	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
482	    }
